#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=10

SITE_DOMAIN="stanzy-immigration-consulting.com"

banner "Cloudflare R2: file storage (#87)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "What we'll set up"
say "Every file the app stores moves to Cloudflare R2:"
note "  • a PRIVATE bucket: Documents de service and Preuves de paiement (encrypted)"
note "  • a PUBLIC bucket: blog images and the TikTok carousel"
note "  • one API token for both, the CORS rule that lets the browser upload,"
note "    and the GitHub secrets the weekly TikTok job needs."
say ""
note "R2's free tier covers 10 GB and has no download fees. Cloudflare asks for a"
note "payment method before turning R2 on, even on the free tier."
note "The same buckets serve your machine and the live site."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: turn on R2"
open_url "https://dash.cloudflare.com/?to=/:account/r2/overview"
step "Sign in (or create a Cloudflare account)."
step "If R2 isn't on yet: « Purchase R2 / Add R2 subscription » (free plan), add a payment method."
step "On the R2 overview, find « Account ID » on the right and copy it."
ask R2_ACCOUNT_ID "Paste the Account ID:"
write_env R2_ACCOUNT_ID "$R2_ACCOUNT_ID"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "The private bucket"
open_url "https://dash.cloudflare.com/?to=/:account/r2/new"
step "Bucket name: stanzy-private (or your own). Location: Automatic. Storage class: Standard."
step "« Create bucket ». Leave its public access OFF."
ask R2_PRIVATE_BUCKET "Its exact name [stanzy-private]:" || true
write_env R2_PRIVATE_BUCKET "${R2_PRIVATE_BUCKET:-stanzy-private}"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "The public bucket"
open_url "https://dash.cloudflare.com/?to=/:account/r2/new"
step "Bucket name: stanzy-public. Location: Automatic → « Create bucket »."
ask R2_PUBLIC_BUCKET "Its exact name [stanzy-public]:" || true
write_env R2_PUBLIC_BUCKET "${R2_PUBLIC_BUCKET:-stanzy-public}"
say ""
say "Now let visitors read it: open the bucket → Settings → Public access."
if confirm "Is $SITE_DOMAIN's DNS managed by Cloudflare?"; then
  step "« Custom Domains » → Connect domain → files.$SITE_DOMAIN → Continue → Connect."
  step "Wait until its status reads Active (a minute or two)."
  note "Your address will be https://files.$SITE_DOMAIN"
else
  step "« R2.dev subdomain » → Allow → type allow → Allow. Copy the https://pub-….r2.dev address."
  note "r2.dev is rate-limited by Cloudflare: fine to start; a custom domain is better once"
  note "the DNS moves to Cloudflare (rerun this wizard then)."
fi
ask NEXT_PUBLIC_R2_PUBLIC_URL "Paste the public address (https://…, no trailing slash):"
write_env NEXT_PUBLIC_R2_PUBLIC_URL "${NEXT_PUBLIC_R2_PUBLIC_URL%/}"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "CORS: let the browser upload"
say "Do this on BOTH buckets: open the bucket → Settings → CORS policy → Add CORS policy,"
say "replace the JSON with this, then Save:"
printf '\n%s' "$DIM"
cat <<JSON
[
  {
    "AllowedOrigins": [
      "http://localhost:3000",
      "http://admin.localhost:3000",
      "https://$SITE_DOMAIN",
      "https://www.$SITE_DOMAIN",
      "https://admin.$SITE_DOMAIN"
    ],
    "AllowedMethods": ["GET", "PUT", "HEAD"],
    "AllowedHeaders": ["content-type"],
    "MaxAgeSeconds": 3600
  }
]
JSON
printf '%s\n' "$RESET"
note "Vercel preview addresses aren't listed: uploads only work locally and on the live site."
open_url "https://dash.cloudflare.com/?to=/:account/r2/overview"
pause "Press Enter once both buckets have the policy"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "The API token"
open_url "https://dash.cloudflare.com/?to=/:account/r2/api-tokens"
step "« Create Account API token » (or « Create API token »)."
step "Name: stanzy-app. Permissions: Object Read & Write."
step "Specify bucket(s): Apply to specific buckets only → both buckets. TTL: Forever."
step "« Create API Token ». The next page shows the keys ONCE: copy them now."
ask R2_ACCESS_KEY_ID "Paste the Access Key ID:"
ask_secret R2_SECRET_ACCESS_KEY "Paste the Secret Access Key:"
write_env R2_ACCESS_KEY_ID "$R2_ACCESS_KEY_ID"
write_env R2_SECRET_ACCESS_KEY "$R2_SECRET_ACCESS_KEY"
note "Ignore the « Token value » shown there: the app uses the Access Key pair."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Check everything works"
say "Writing, reading and deleting a small file in each bucket, and checking CORS…"
say ""
until node --env-file="$ENV_FILE" scripts/check-r2.mjs \
  http://localhost:3000 http://admin.localhost:3000 "https://$SITE_DOMAIN" "https://admin.$SITE_DOMAIN"; do
  say ""
  warn "Fix what's marked ✗ in the Cloudflare dashboard (CORS can take a minute to apply)."
  confirm "Check again?" || { SKIPPED+=("R2 check: run node --env-file=.env scripts/check-r2.mjs"); break; }
done
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "GitHub: secrets for the weekly TikTok job"
say "The « Refresh TikTok carousel » workflow uploads the videos to the public bucket."
set_secret R2_ACCOUNT_ID "$R2_ACCOUNT_ID"
set_secret R2_ACCESS_KEY_ID "$R2_ACCESS_KEY_ID"
set_secret R2_SECRET_ACCESS_KEY "$R2_SECRET_ACCESS_KEY"
set_secret R2_PUBLIC_BUCKET "$R2_PUBLIC_BUCKET"
set_secret R2_PUBLIC_URL "$NEXT_PUBLIC_R2_PUBLIC_URL"
note "The old BLOB_READ_WRITE_TOKEN secret is no longer read; delete it whenever you like."
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Vercel: the same values for the live site"
open_url "https://vercel.com/dashboard"
step "Open the project stanzy-immigration-consulting-com → Settings → Environment Variables."
step "Add these six, for Production and Preview, copying each value from $ENV_FILE:"
note "    R2_ACCOUNT_ID  R2_ACCESS_KEY_ID  R2_SECRET_ACCESS_KEY (mark it Sensitive)"
note "    R2_PRIVATE_BUCKET  R2_PUBLIC_BUCKET  NEXT_PUBLIC_R2_PUBLIC_URL"
step "Check DOSSIER_FILES_KEY is there too, with the same value as in $ENV_FILE."
note "They take effect on the next deploy, which merging the PR triggers."
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Real emails (optional)"
say "Without RESEND_API_KEY in $ENV_FILE, emails on your machine are only printed in the"
say "dev-server terminal. With it, they really go out, from your machine too."
if confirm "Send real emails when testing locally?"; then
  open_url "https://resend.com/domains"
  step "Check notifications.$SITE_DOMAIN and auth.$SITE_DOMAIN both show Verified"
  step "(if not, add each and copy its DNS records)."
  open_url "https://resend.com/api-keys"
  step "« Create API Key » → Permission: Sending access → Domain: All domains → Add. Copy it."
  ask_secret RESEND_API_KEY "Paste the Resend API key:"
  write_env RESEND_API_KEY "$RESEND_API_KEY"
  ask EMAIL_FROM "Sender for Dossiers and Factures [Stanzy Immigration <dossiers@notifications.$SITE_DOMAIN>]:" || true
  write_env EMAIL_FROM "${EMAIL_FROM:-Stanzy Immigration <dossiers@notifications.$SITE_DOMAIN>}"
  ask AUTH_EMAIL_FROM "Sender for account emails [Stanzy Immigration <compte@auth.$SITE_DOMAIN>]:" || true
  write_env AUTH_EMAIL_FROM "${AUTH_EMAIL_FROM:-Stanzy Immigration <compte@auth.$SITE_DOMAIN>}"
  warn "Test accounts now receive real emails: sign them up with addresses you own."
else
  note "Kept as is: emails stay in the terminal on this machine."
fi
say ""
step "Restart 'npm run dev' so it reads the new $ENV_FILE."
pause "Press Enter to finish"

finish
}

run_wizard "$@"; exit
